+    padding: 0.7rem 1rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+    font-size: 0.9rem;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #444;
+}
+
+.current-badge {
+    font-size: 0.75rem;
+    background: #e8f0fe;
+    color: #1a73e8;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-weight: 500;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    padding: 2rem;
+    border-radius: 12px;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
+}
+
+.modal-dialog h3 {
+    margin-top: 0;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.4rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+.radio-label input[type="radio"] {
+    accent-color: #1a73e8;
+}
+
+/* Live Preview */
+.live-preview {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #dadce0;
+    border-radius: 8px;
+    transition: all 0.2s;
+}
+
+.live-preview h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.live-preview .preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem 1rem;
+    border: 1px solid #dadce0;
+    border-radius: 6px;
+    background: #f8f9fa;
+}
+
+/* Preview theme variants */
+.preview-theme-light {
+    background: #ffffff;
+    color: #202124;
+}
+
+.preview-theme-dark {
+    background: #202124;
+    color: #e8eaed;
+}
+
+.preview-theme-dark .preview-card {
+    background: #303134;
+    border-color: #5f6368;
+    color: #e8eaed;
+}
+
+.preview-theme-system {
+    background: #f8f9fa;
+    color: #202124;
+}
+
+/* Preview font sizes */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview compact */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+.preview-compact .preview-card {
+    padding: 0.4rem 0.6rem;
+    margin-top: 0.4rem;
+}
+
+/* Toast */
+.toast {
+    position: fixed;
+    bottom: 2rem;
+    right: 2rem;
+    padding: 0.85rem 1.5rem;
+    border-radius: 8px;
+    font-size: 0.9rem;
+    font-weight: 500;
+    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
+    z-index: 2000;
+    animation: slideIn 0.2s ease-out;
+}
+
+.toast.success {
+    background: #1e8e3e;
+    color: white;
+}
+
+.toast.error {
+    background: #d93025;
+    color: white;
+}
+
+@keyframes slideIn {
+    from {
+        transform: translateY(1rem);
+        opacity: 0;
+    }
+    to {
+        transform: translateY(0);
+        opacity: 1;
+    }
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 200px;
+    color: #666;
+    font-size: 1.1rem;
+}
+

